import assert from 'node:assert/strict';
import http from 'node:http';
import {existsSync,readFileSync,unlinkSync} from 'node:fs';
import {spawn} from 'node:child_process';
import {query} from '@anthropic-ai/claude-agent-sdk';
const root='/workspace/native-sdk';
let giveTool=true,permissionCalls=0;let calls=[],hold=false,held=[],children=[],results=[],events=[],values=[],waiting=[];
const input={ [Symbol.asyncIterator](){return this}, next(){return values.length?Promise.resolve({value:values.shift(),done:false}):new Promise(r=>waiting.push(r))} };
const send=text=>{const x={type:'user',message:{role:'user',content:text},parent_tool_use_id:null,session_id:'',uuid:crypto.randomUUID()};waiting.length?waiting.shift()({value:x,done:false}):values.push(x);return x.uuid};
const until=async(p)=>{for(let i=0;i<600;i++){if(p())return;await new Promise(r=>setTimeout(r,20))}throw Error('timeout '+JSON.stringify({calls:calls.length,events:events.map(x=>x.type+':'+(x.subtype||''))}))};
const server=http.createServer(async(req,res)=>{let raw='';for await(const c of req)raw+=c;const b=JSON.parse(raw||'{}');if(req.url.includes('count_tokens')){res.end(JSON.stringify({input_tokens:10}));return}if(!req.url.includes('/messages')){res.writeHead(404);res.end('{}');return}calls.push(b);if(hold){held.push(res);return}reply(res,b)});
function reply(res,b){const m={id:'msg_'+crypto.randomUUID(),type:'message',role:'assistant',model:b.model,content:[],stop_reason:null,stop_sequence:null,usage:{input_tokens:10,output_tokens:1}};
if(!b.stream){res.setHeader('Content-Type','application/json');res.end(JSON.stringify({...m,content:[{type:'text',text:'offline reply'}],stop_reason:'end_turn'}));return}
const useTool=giveTool&&(b.tools??[]).some(x=>x.name==='Bash');if(useTool)giveTool=false;res.writeHead(200,{'content-type':'text/event-stream'});const e=(type,data)=>res.write('event: '+type+'\ndata: '+JSON.stringify({type,...data})+'\n\n');e('message_start',{message:m});if(useTool){e('content_block_start',{index:0,content_block:{type:'tool_use',id:'tool_stop',name:'Bash',input:{}}});e('content_block_delta',{index:0,delta:{type:'input_json_delta',partial_json:JSON.stringify({command:'echo $$ > /workspace/native-sdk/isolated/claude-tool-owner; /bin/sleep 30; echo done > /workspace/native-sdk/isolated/claude-tool-finished',description:'offline held tool'})}})}else{e('content_block_start',{index:0,content_block:{type:'text',text:''}});e('content_block_delta',{index:0,delta:{type:'text_delta',text:'offline reply'}})}e('content_block_stop',{index:0});e('message_delta',{delta:{stop_reason:useTool?'tool_use':'end_turn',stop_sequence:null},usage:{output_tokens:2}});e('message_stop',{});res.end();}
await new Promise(r=>server.listen(18479,'127.0.0.1',r));
function make(resume){console.error('PHASE claude query',new Date().toISOString(),{resume:Boolean(resume)});return query({prompt:input,options:{cwd:root+'/isolated',pathToClaudeCodeExecutable:root+'/node_modules/@anthropic-ai/claude-agent-sdk-linux-x64/claude',settingSources:[],tools:['Bash'],canUseTool:async(name,input,options)=>{permissionCalls++;return {behavior:'allow',updatedInput:input}},model:'claude-sonnet-4-5',resume,persistSession:true,env:{...process.env,ANTHROPIC_API_KEY:'offline-fixture',ANTHROPIC_BASE_URL:'http://127.0.0.1:18479',CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC:'1',DISABLE_AUTOUPDATER:'1'},spawnClaudeCodeProcess:o=>{const c=spawn(o.command,o.args,{cwd:o.cwd,env:o.env,stdio:['pipe','pipe','pipe']});children.push(c);c.stderr.on('data',b=>console.error('CLAUDE_STDERR',new Date().toISOString(),b.toString().slice(0,4000)));c.on('error',e=>console.error('CLAUDE_SPAWN_ERROR',String(e)));c.on('exit',(code,signal)=>console.error('CLAUDE_EXIT',new Date().toISOString(),{code,signal}));console.error('PHASE claude spawned',new Date().toISOString(),c.pid);return c}}})}
let q=make();let reader=(async()=>{for await(const m of q){events.push(m);if(m.type==='result')results.push(m)}})();
const marker=root+'/isolated/claude-tool-owner',finished=root+'/isolated/claude-tool-finished';for(const p of [marker,finished])if(existsSync(p))unlinkSync(p);
let toolPID;try{send('run offline held command');await until(()=>existsSync(marker));toolPID=Number(readFileSync(marker,'utf8').trim());const session=events.find(x=>x.type==='system'&&x.subtype==='init').session_id;const queuedUUID=send('queued before cancellation');await new Promise(r=>setTimeout(r,100));q.close();await reader;await until(()=>children[0].exitCode!==null||children[0].signalCode!==null);const alive=()=>{try{process.kill(toolPID,0);return true}catch{return false}};await until(()=>!alive());assert.equal(existsSync(finished),false);const before=calls.length;waiting=[];values=[];q=make(session);reader=(async()=>{for await(const m of q){events.push(m);if(m.type==='result')results.push(m)}})();await q.initializationResult();await new Promise(r=>setTimeout(r,200));assert.equal(calls.length,before);const count=results.length;send('new input after owner close');await until(()=>results.length>count);assert.equal(results.at(-1).subtype,'success');assert.equal(results.at(-1).result,'offline reply');q.close();await reader;await until(()=>children[1].exitCode!==null||children[1].signalCode!==null);console.log(JSON.stringify({case:'Claude-native-close-during-tool-with-queued-input',ownerExitObserved:true,toolShellGone:true,toolDidNotFinish:true,reopenInert:true,freshInputSuccess:true}));}finally{q.close();for(const c of children)if(c.exitCode===null&&c.signalCode===null)c.kill('SIGKILL');if(toolPID)try{process.kill(-toolPID,'SIGKILL')}catch{}server.close()}
